package org.eclipse.rdf4j.federated.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.federated.structures.FedXDataset;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF4J;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.FallbackDataset;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.junit.jupiter.api.Test;

class FedXUtilTest {
	@Test
	void endpointOnlyFallbackRemainsAnImplicitDataset() {
		FedXDataset primary = new FedXDataset(null);
		primary.addEndpoint("primary");
		FedXDataset fallback = new FedXDataset(null);
		fallback.addEndpoint("fallback");

		Dataset wrapper = FallbackDataset.fallback(primary, fallback);

		assertThat(FedXUtil.toRdfDataset(wrapper)).isNull();
	}

	@Test
	void endpointOnlyFallbackIsImplicitForGraphSelectionHelpers() {
		FedXDataset primary = new FedXDataset(null);
		primary.addEndpoints(List.of("first", "second"));
		FedXDataset fallback = new FedXDataset(null);
		fallback.addEndpoint("third");
		Dataset wrapper = FallbackDataset.fallback(primary, fallback);
		var graph = SimpleValueFactory.getInstance().createIRI("urn:graph");
		StatementPattern selectedGraph = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g", graph, true, true));
		StatementPattern defaultGraph = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));

		assertThat(FedXUtil.isContextAvailable(selectedGraph, wrapper)).isTrue();
		assertThat(FedXUtil.toContexts(selectedGraph, wrapper)).containsExactly(graph);
		assertThat(FedXUtil.isContextAvailable(defaultGraph, wrapper)).isTrue();
		assertThat(FedXUtil.toContexts(defaultGraph, wrapper)).isEmpty();

		Dataset defaultBehavior = FallbackDataset.fallback(
				new FedXDataset(new SimpleDataset()), new FedXDataset(new SimpleDataset()));
		assertThat(FedXUtil.isContextAvailable(selectedGraph, defaultBehavior)).isTrue();
		assertThat(FedXUtil.toContexts(selectedGraph, defaultBehavior)).containsExactly(graph);
		assertThat(FedXUtil.isContextAvailable(defaultGraph, defaultBehavior)).isTrue();
		assertThat(FedXUtil.toContexts(defaultGraph, defaultBehavior)).isEmpty();
	}

	@Test
	void bothEmptyReadSetsPreserveDefaultsAndMutationMetadata() {
		var vf = SimpleValueFactory.getInstance();
		var target = vf.createIRI("urn:mutation:target");
		var alias = RDF4J.NIL;
		SimpleDataset defaults = new SimpleDataset();
		defaults.setDefaultInsertGraph(target);
		defaults.addDefaultRemoveGraph(target);
		Dataset effective = FedXUtil.toRdfDataset(new FedXDataset(defaults));
		assertThat(effective).isSameAs(defaults);
		assertThat(effective.getDefaultInsertGraph()).isEqualTo(target);
		assertThat(effective.getDefaultRemoveGraphs()).containsExactly(target);
		StatementPattern defaultPattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		StatementPattern namedPattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g"));
		StatementPattern fixedAlias = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g", alias, true, true));
		assertThat(FedXUtil.isContextAvailable(defaultPattern, effective)).isTrue();
		assertThat(FedXUtil.isContextAvailable(namedPattern, effective)).isTrue();
		assertThat(FedXUtil.toContexts(namedPattern, effective)).isEmpty();
		assertThat(FedXUtil.toContexts(fixedAlias, effective)).containsExactly((Resource) null);

		SimpleDataset namedOnly = new SimpleDataset();
		namedOnly.addNamedGraph(target);
		assertThat(FedXUtil.isContextAvailable(defaultPattern, namedOnly)).isFalse();
		assertThat(FedXUtil.isContextAvailable(namedPattern, namedOnly)).isTrue();
		SimpleDataset defaultOnly = new SimpleDataset();
		defaultOnly.addDefaultGraph(target);
		assertThat(FedXUtil.isContextAvailable(namedPattern, defaultOnly)).isFalse();
		assertThat(FedXUtil.isContextAvailable(defaultPattern, defaultOnly)).isTrue();
	}

	@Test
	void defaultReadBehaviorAndFallbackGraphSetPrecedenceArePreserved() {
		Dataset explicitEmpty = new SimpleDataset();
		Dataset convertedEmpty = FedXUtil.toRdfDataset(FallbackDataset.fallback(
				new FedXDataset(explicitEmpty), new FedXDataset(new SimpleDataset())));
		assertThat(convertedEmpty).isNotNull();
		assertThat(convertedEmpty.getDefaultGraphs()).isEmpty();
		assertThat(convertedEmpty.getNamedGraphs()).isEmpty();

		var vf = SimpleValueFactory.getInstance();
		var primaryGraph = vf.createIRI("urn:primary");
		var fallbackGraph = vf.createIRI("urn:fallback");
		SimpleDataset primary = new SimpleDataset();
		primary.addNamedGraph(primaryGraph);
		SimpleDataset fallback = new SimpleDataset();
		fallback.addNamedGraph(fallbackGraph);

		Dataset convertedFallback = FedXUtil.toRdfDataset(
				FallbackDataset.fallback(new FedXDataset(primary), new FedXDataset(fallback)));

		assertThat(convertedFallback.getNamedGraphs()).containsExactly(primaryGraph);
	}
}
